INSERT INTO "settings" ("key","value") VALUES('testimonials_list','[{"name":"Dr. Rajesh Kumar","role":"Hospital Director, Darbhanga","text":"MJ DEVELOPERS has been supplying medical equipment to our hospital for 3 years. Their service is prompt and quality is excellent."},{"name":"Priya Sharma","role":"Facility Manager, Patna","text":"Their housekeeping and security team is professional and reliable. We have been very satisfied with their services."},{"name":"Amit Verma","role":"Project Manager, Construction Co.","text":"From manpower supply to complete construction, they handle everything with expertise. Highly recommended!"}]');
INSERT INTO "settings" ("key","value") VALUES('faqs_list','[{"q":"What services does MJ DEVELOPERS provide?","a":"We provide 15+ integrated services including civil construction, housekeeping, security, medical equipment supply, manpower supply, sanitization, and more."},{"q":"Which areas do you serve?","a":"We have a strong presence across Bihar with offices in Darbhanga, Laheriasarai, and 8 other branches."},{"q":"Are your services ISO certified?","a":"Yes, we are ISO 9001:2015 certified, MSME registered, and hold a valid Drug License."},{"q":"How can I get a quote for my project?","a":"Simply contact us via phone, email, or WhatsApp. Our team will provide a customized quote within 24 hours."},{"q":"Do you provide 24/7 emergency services?","a":"Yes, we offer 24/7 support for security, e-ambulance, and facility management services."}]');
INSERT INTO "settings" ("key","value") VALUES('why_choose_us','[{"icon":"🏆","title":"Experienced Team","description":"Highly trained professionals with years of experience."},{"icon":"⏱️","title":"24/7 Support","description":"Round-the-clock customer support and emergency services."},{"icon":"✅","title":"Quality Assurance","description":"ISO 9001:2015 certified processes for consistent quality."},{"icon":"💰","title":"Cost Effective","description":"Competitive pricing without compromising on quality."},{"icon":"🤝","title":"Trusted Partner","description":"Trusted by 1000+ customers across Bihar."}]');
